/** npm run docs:letters — writes docs/LETTERS.md, the specification of every Forever Letter, from the code that defines them. */
import { writeFileSync } from "node:fs";
import { LETTERS, LETTER_CATEGORIES } from "../src/domain/letters";
import { describeExperience, musicLabel } from "../src/domain/letters/describe";
import { letterImage } from "../src/domain/letters/images";

const out: string[] = [
  "# Forever Letters — the specification of all fifty",
  "",
  "_Generated by `npm run docs:letters` from `src/domain/letters/specs/`. Do not edit by hand: edit the specs and run it again._",
  "",
  "Every experience is data: a palette, a type pairing, a motion profile, a layout, an ambient effect, a backdrop photograph, the fields its sender fills in, and an ordered list of beats (one opening, then games, reveals and a question) taken from the shared library. See [FOREVER-LETTERS.md](FOREVER-LETTERS.md) for how it works.",
  "",
  "| No. | Experience | Chapter | Tone | Opening | Motion · layout | Backdrop | Answer |",
  "|---|---|---|---|---|---|---|---|",
];
for (const l of LETTERS) {
  const gate = l.beats[0].type === "gate" ? l.beats[0].style : "";
  const cat = LETTER_CATEGORIES.find((c) => c.key === l.category)?.name ?? l.category;
  out.push(`| ${String(l.n).padStart(2, "0")} | [${l.title}](/for-my-love/letters/${l.slug}) | ${cat} | ${l.tone} | ${gate} | ${l.motion} · ${l.layout} | ${l.backdrop} | ${l.reply ? (l.playfulNo ? "asks · moving “No” available" : "asks") : "never asks"} |`);
}
for (const cat of LETTER_CATEGORIES) {
  out.push("", `## ${cat.name}`, "", `_${cat.blurb}_`);
  for (const l of LETTERS.filter((x) => x.category === cat.key)) {
    const im = letterImage(l.backdrop);
    out.push(
      "", `### ${String(l.n).padStart(2, "0")} · ${l.title}`, "",
      `**Purpose.** ${l.purpose} **Feeling.** ${l.feeling}`, "",
      `**Visual direction.** ${l.direction}`, "",
      `**Look.** ${l.fonts.display} / ${l.fonts.body}${l.fonts.script ? ` / ${l.fonts.script}` : ""} · palette ${[l.palette.bg, l.palette.accent, l.palette.accent2].join(" ")} · ${l.motion} motion · ${l.layout} layout · ${l.ambient} ambience · ${l.treatment} grade · suggested sound: ${musicLabel(l)}.`, "",
      `**Backdrop.** \`${l.backdrop}\` — ${im?.alt ?? ""} (${im?.author}, ${im?.licence}).`, "",
      "**Moments.**", "", ...describeExperience(l).map((m, i) => `${i + 1}. ${m}`), "",
      `**Fields.** ${l.fields.map((f) => f.label + (f.required ? " *" : "")).join(" · ")}`, "",
      `**Care.** ${l.care.join(" ")}`,
    );
  }
}
writeFileSync("docs/LETTERS.md", out.join("\n") + "\n");
console.log(`docs/LETTERS.md — ${LETTERS.length} experiences`);

// ── the image manifest, with where every photograph is used ───────────────────────────────────────────
import { LETTER_IMAGES } from "../src/domain/letters/images";
const uses = new Map<string, string[]>();
const add = (id: string, where: string) => uses.set(id, [...(uses.get(id) ?? []), where]);
for (const l of LETTERS) {
  add(l.backdrop, `${l.slug} · backdrop (opening and every screen), ${l.treatment} grade`);
  for (const f of l.fields) for (const s of [f.kind === "list" ? f.samples?.flatMap((x) => Object.values(x)) : [f.sample ?? ""]].flat()) if (s && LETTER_IMAGES.some((i) => i.id === s)) add(s, `${l.slug} · demonstration photograph (${f.key})`);
}
const img: string[] = [
  "# Forever Letters — image manifest", "",
  "_Generated by `npm run docs:letters`. Source of truth: `src/domain/letters/images.ts`. Checked by `npm run letters:check`._", "",
  "Every photograph is bundled (never hot-linked), processed by `npm run letters:images` into a 2:3 crop on its focal point, and listed here with its licence, its description and everywhere it is used. A real letter always uses its sender's own photographs for anything personal; these supply atmosphere and stand in for a couple in the public demonstrations only. Photographs marked **people** show someone who can be recognised and are never the backdrop of a closure experience.", "",
  "| Id | Original | Author | Licence | Focal | People | Description | Used in |", "|---|---|---|---|---|---|---|---|",
];
for (const i of LETTER_IMAGES) img.push(`| \`${i.id}\` | \`${i.ref}\` | ${i.author} | ${i.licence} | ${i.focal.x},${i.focal.y} | ${i.people ? "yes" : "no"} | ${i.alt} | ${(uses.get(i.id) ?? ["—"]).join("<br>")} |`);
writeFileSync("docs/LETTERS-IMAGES.md", img.join("\n") + "\n");
console.log(`docs/LETTERS-IMAGES.md — ${LETTER_IMAGES.length} photographs`);
